-- =============================================================================
-- NINHO — CATÁLOGO SEMÂNTICO: 04_meta_relacionamento.sql (PROJETO: GLD)
-- =============================================================================

MERGE INTO DW_GLD.META_RELACIONAMENTO dst
USING (SELECT 'GLD' AS PROJETO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETO_ORIGEM, 'DIM_ORGAO_PUBLICO' AS COLUNA_ORIGEM, 'VW_GLD_DIM_ORGAO_PUBLICO_ATUAL' AS OBJETO_DESTINO, 'DIMENSION_KEY' AS COLUNA_DESTINO, 'LEFT' AS TIPO_JOIN, 'N:1' AS CARDINALIDADE, 'Join dimensional N:1 entre VW_GLD_EVENTO_LICITACAO_CONTRATO e VW_GLD_DIM_ORGAO_PUBLICO_ATUAL com fallback sentinela (-1).' AS OBSERVACAO FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.OBJETO_ORIGEM = src.OBJETO_ORIGEM AND dst.COLUNA_ORIGEM = src.COLUNA_ORIGEM AND dst.OBJETO_DESTINO = src.OBJETO_DESTINO AND dst.COLUNA_DESTINO = src.COLUNA_DESTINO)
WHEN MATCHED THEN UPDATE SET dst.TIPO_JOIN = src.TIPO_JOIN, dst.CARDINALIDADE = src.CARDINALIDADE, dst.OBSERVACAO = src.OBSERVACAO
WHEN NOT MATCHED THEN INSERT (PROJETO, OBJETO_ORIGEM, COLUNA_ORIGEM, OBJETO_DESTINO, COLUNA_DESTINO, TIPO_JOIN, CARDINALIDADE, OBSERVACAO)
VALUES (src.PROJETO, src.OBJETO_ORIGEM, src.COLUNA_ORIGEM, src.OBJETO_DESTINO, src.COLUNA_DESTINO, src.TIPO_JOIN, src.CARDINALIDADE, src.OBSERVACAO);

MERGE INTO DW_GLD.META_RELACIONAMENTO dst
USING (SELECT 'GLD' AS PROJETO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETO_ORIGEM, 'DIM_FORNECEDOR' AS COLUNA_ORIGEM, 'VW_GLD_DIM_FORNECEDOR_ATUAL' AS OBJETO_DESTINO, 'DIMENSION_KEY' AS COLUNA_DESTINO, 'LEFT' AS TIPO_JOIN, 'N:1' AS CARDINALIDADE, 'Join dimensional N:1 entre VW_GLD_EVENTO_LICITACAO_CONTRATO e VW_GLD_DIM_FORNECEDOR_ATUAL com fallback sentinela (-1).' AS OBSERVACAO FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.OBJETO_ORIGEM = src.OBJETO_ORIGEM AND dst.COLUNA_ORIGEM = src.COLUNA_ORIGEM AND dst.OBJETO_DESTINO = src.OBJETO_DESTINO AND dst.COLUNA_DESTINO = src.COLUNA_DESTINO)
WHEN MATCHED THEN UPDATE SET dst.TIPO_JOIN = src.TIPO_JOIN, dst.CARDINALIDADE = src.CARDINALIDADE, dst.OBSERVACAO = src.OBSERVACAO
WHEN NOT MATCHED THEN INSERT (PROJETO, OBJETO_ORIGEM, COLUNA_ORIGEM, OBJETO_DESTINO, COLUNA_DESTINO, TIPO_JOIN, CARDINALIDADE, OBSERVACAO)
VALUES (src.PROJETO, src.OBJETO_ORIGEM, src.COLUNA_ORIGEM, src.OBJETO_DESTINO, src.COLUNA_DESTINO, src.TIPO_JOIN, src.CARDINALIDADE, src.OBSERVACAO);

MERGE INTO DW_GLD.META_RELACIONAMENTO dst
USING (SELECT 'GLD' AS PROJETO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETO_ORIGEM, 'DIM_TEMPO' AS COLUNA_ORIGEM, 'VW_GLD_DIM_TEMPO_ATUAL' AS OBJETO_DESTINO, 'DIMENSION_KEY' AS COLUNA_DESTINO, 'LEFT' AS TIPO_JOIN, 'N:1' AS CARDINALIDADE, 'Join dimensional N:1 entre VW_GLD_EVENTO_LICITACAO_CONTRATO e VW_GLD_DIM_TEMPO_ATUAL com fallback sentinela (-1).' AS OBSERVACAO FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.OBJETO_ORIGEM = src.OBJETO_ORIGEM AND dst.COLUNA_ORIGEM = src.COLUNA_ORIGEM AND dst.OBJETO_DESTINO = src.OBJETO_DESTINO AND dst.COLUNA_DESTINO = src.COLUNA_DESTINO)
WHEN MATCHED THEN UPDATE SET dst.TIPO_JOIN = src.TIPO_JOIN, dst.CARDINALIDADE = src.CARDINALIDADE, dst.OBSERVACAO = src.OBSERVACAO
WHEN NOT MATCHED THEN INSERT (PROJETO, OBJETO_ORIGEM, COLUNA_ORIGEM, OBJETO_DESTINO, COLUNA_DESTINO, TIPO_JOIN, CARDINALIDADE, OBSERVACAO)
VALUES (src.PROJETO, src.OBJETO_ORIGEM, src.COLUNA_ORIGEM, src.OBJETO_DESTINO, src.COLUNA_DESTINO, src.TIPO_JOIN, src.CARDINALIDADE, src.OBSERVACAO);

COMMIT;
